    {
      "keystrokes": "python3 - <<'PY'
import re
lines=open('/app/prompt_ocr6.txt').read().splitlines()
ents=[]
for i,l in enumerate(lines,1):
    m=re.match(r'(\d+)\s+(.*)', l)
    if not m: continue
    fr=int(m.group(1)); txt=m.group(2).strip()
    ents.append((fr,txt))
def clean(t):
    t=t.replace('_','').strip()
    if t.startswith('>'): t=t[1:].strip()
    return t.strip()
def has_letter(t):
    return bool(re.search(r'[A-Za-z]', t))
groups=[]; cur=[]; lastfr=None
for fr,txt in ents:
    c=clean(txt)
    if txt.startswith('>') and has_letter(c):
        if cur and lastfr is not None and fr-lastfr>6:
            groups.append(cur); cur=[]
        cur.append((fr,txt,c)); lastfr=fr
    else:
        if cur: groups.append(cur); cur=[]
        lastfr=fr
if cur: groups.append(cur)
for idx,g in enumerate(groups,1):
    longest=max(g,key=lambda x:len(x[2]))
    print(f'{idx:03d} {g[0][0]:04d}-{g[-1][0]:04d} {longest[2]}')
PY
",
      "duration": 0.1
    }
  ]
}
